SELECT p.*,pt.name AS project_name,u.user_name
FROM paper p
LEFT JOIN project_type pt ON pt.id = p.project_id
LEFT JOIN user u ON u.id = p.user_id


        AND p.id = #{id}


        AND p.name LIKE concat('%',#{name},'%')


        AND p.user_id = #{userId}


        AND p.detail LIKE concat('%',#{detail},'%')


        AND p.limit_time = #{limitTime}


        AND p.is_show = #{isShow}


        AND p.project_id = #{projectId}


        AND p.create_time BETWEEN #{startTime} AND #{endTime}


ORDER BY p.create_time DESC

    LIMIT #{current},#{size}

